<script lang="ts">
 import {onMount}from'svelte';import * as Dialog from '$lib/components/ui/dialog';import{Button}from'$lib/components/ui/button';import{cropGeometry}from'./crop.mjs';
 let{source,kind,onapply,oncancel}:{source:string;kind:'avatar'|'banner';onapply:(data:string)=>Promise<void>;oncancel:()=>void}=$props();
 let image=$state<HTMLImageElement>(),canvas=$state<HTMLCanvasElement>(),zoom=$state(1),x=$state(50),y=$state(50),busy=$state(false),error=$state('');
 const width=$derived(kind==='avatar'?512:1600),height=$derived(kind==='avatar'?512:600);
 onMount(()=>{const next=new Image();next.src=source;void next.decode().then(()=>{if(next.naturalWidth<64||next.naturalHeight<64)throw new Error('Choose an image at least 64 pixels wide and tall.');image=next;}).catch(e=>error=e.message);});
 $effect(()=>{if(!canvas||!image)return;const g=cropGeometry(image.naturalWidth,image.naturalHeight,width,height,zoom,x,y);const ctx=canvas.getContext('2d');if(!ctx)return;ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.drawImage(image,g.x,g.y,g.width,g.height);});
 async function apply(){if(!canvas||!image)return;busy=true;error='';try{await onapply(canvas.toDataURL('image/jpeg',.88));}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<Dialog.Root open onOpenChange={open=>{if(!open&&!busy)oncancel();}}><Dialog.Content class="sm:max-w-lg"><Dialog.Header><Dialog.Title>Adjust your {kind==='avatar'?'profile photo':'channel banner'}</Dialog.Title><Dialog.Description>Zoom and position the image inside the frame. You can review it before saving your profile.</Dialog.Description></Dialog.Header><div class="crop-preview" class:avatar={kind==='avatar'}><canvas bind:this={canvas} {width} {height} aria-label={`${kind} crop preview`}></canvas></div>{#if error}<p role="alert" class="text-sm text-destructive">{error}</p>{/if}<div class="crop-controls"><label>Zoom <input type="range" min="1" max="3" step=".01" bind:value={zoom} disabled={busy}/></label><label>Horizontal position <input type="range" min="0" max="100" bind:value={x} disabled={busy}/></label><label>Vertical position <input type="range" min="0" max="100" bind:value={y} disabled={busy}/></label></div><Dialog.Footer><Button variant="outline" disabled={busy} onclick={oncancel}>Cancel</Button><Button disabled={busy||!image} onclick={apply}>{busy?'Uploading…':'Use this image'}</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
<style>.crop-preview{overflow:hidden;border:1px solid var(--border);background:var(--muted);border-radius:8px}.crop-preview canvas{display:block;width:100%;height:auto}.crop-preview.avatar{width:min(100%,240px);margin-inline:auto;border-radius:50%}.crop-controls{display:grid;gap:12px}.crop-controls label{display:grid;gap:7px;font-size:12px;color:var(--muted-foreground)}.crop-controls input{width:100%;accent-color:var(--primary);min-height:24px}</style>
